-- 세트 346: 도커 Dockerfile 직접 쓰기 실습: FROM·RUN·LABEL, WORKDIR, CMD·ENTRYPOINT, ENV·ARG, 빌드 캐시, .dockerignore, 멀티 스테이지, USER
-- 정답·해설은 서버만 안다. 실습 문제의 grade_cmd 는 checks 의 조건을 && 로 이은 것과 같다. docs/specs/spec_docker_dockerfile_set.md
INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs) VALUES
  (346, 1, 'FROM, RUN, LABEL 로 첫 이미지 만들기', '`/tmp/work/Dockerfile` 을 직접 써서 이미지 **`hello:1`** 을 빌드하세요. 조건은 세 가지예요. `alpine` 에서 시작하고, 빌드 중에 `/hello.txt` 파일을 만들어 안에 `hello etude` 를 적고(`RUN`), 이미지에 라벨 `purpose=training` 을 붙입니다(`LABEL`).', '`FROM` 이 시작 이미지, `RUN` 은 **빌드할 때** 한 번 실행할 명령, `LABEL` 은 `키=값` 꼴의 이름표예요. 빌드는 Dockerfile 이 있는 폴더에서 `docker build -t 이름:태그 .` 로 합니다.', 'cd /tmp/work
printf ''FROM alpine\\nRUN echo "hello etude" > /hello.txt\\nLABEL purpose=training\\n'' > Dockerfile
docker build -t hello:1 .
docker run --rm hello:1 cat /hello.txt
docker image inspect -f ''{{.Config.Labels}}'' hello:1

# RUN 은 빌드 때 실행되고 결과가 이미지에 남는다', '["sh", "-c", "docker rm -f $(docker ps -aq) >/dev/null 2>&1; docker rmi -f $(docker images -aq) >/dev/null 2>&1; rm -rf /tmp/work; mkdir -p /tmp/work; docker pull -q alpine >/dev/null 2>&1; true"]', '["sh", "-c", "( docker image inspect hello:1 >/dev/null 2>&1 ) && ( [ \\"$(docker run --rm hello:1 cat /hello.txt 2>/dev/null)\\" = \\"hello etude\\" ] ) && ( [ \\"$(docker image inspect -f ''{{index .Config.Labels \\"purpose\\"}}'' hello:1)\\" = \\"training\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "hello:1 이미지가 있다", "cmd": ["sh", "-c", "docker image inspect hello:1 >/dev/null 2>&1"]}, {"label": "이미지 안에 /hello.txt 가 있고 내용이 맞다", "cmd": ["sh", "-c", "[ \\"$(docker run --rm hello:1 cat /hello.txt 2>/dev/null)\\" = \\"hello etude\\" ]"]}, {"label": "라벨 purpose 가 training 이다", "cmd": ["sh", "-c", "[ \\"$(docker image inspect -f ''{{index .Config.Labels \\"purpose\\"}}'' hello:1)\\" = \\"training\\" ]"]}]', '[{"title": "Docker 공식 문서: Dockerfile reference", "url": "https://docs.docker.com/reference/dockerfile/"}, {"title": "Docker 공식 문서: 빌드 변수 (ARG, ENV)", "url": "https://docs.docker.com/build/building/variables/"}, {"title": "Docker 공식 문서: 빌드 캐시", "url": "https://docs.docker.com/build/cache/"}, {"title": "Docker 공식 문서: 멀티 스테이지 빌드", "url": "https://docs.docker.com/build/building/multi-stage/"}, {"title": "Docker 공식 문서: 빌드 컨텍스트와 .dockerignore", "url": "https://docs.docker.com/build/concepts/context/"}, {"title": "Docker 공식 문서: docker image inspect", "url": "https://docs.docker.com/reference/cli/docker/image/inspect/"}]'),
  (346, 2, 'WORKDIR 로 작업 폴더 정하기', '`/tmp/work` 에 `app.sh` 파일이 있습니다. 이미지 **`wd:1`** 을 빌드하는데, 작업 폴더를 `/srv/app` 으로 정하고(`WORKDIR`) `app.sh` 를 **그 작업 폴더로** 복사해 넣으세요. 컨테이너를 실행해 `pwd` 를 치면 `/srv/app` 이 나와야 하고, `ls` 에 `app.sh` 가 보여야 합니다.', '`WORKDIR` 은 이후 `COPY`, `RUN`, 그리고 컨테이너가 시작될 때의 기본 위치를 바꿔요. 없는 폴더면 알아서 만들어 줍니다. `COPY` 의 도착 경로를 `.` 으로 적으면 작업 폴더가 됩니다.', 'cd /tmp/work
printf ''FROM alpine\\nWORKDIR /srv/app\\nCOPY app.sh .\\n'' > Dockerfile
docker build -t wd:1 .
docker run --rm wd:1 pwd
docker run --rm wd:1 ls

# 이미지 설정의 Config.WorkingDir 에 기록된다', '["sh", "-c", "docker rm -f $(docker ps -aq) >/dev/null 2>&1; docker rmi -f $(docker images -aq) >/dev/null 2>&1; rm -rf /tmp/work; mkdir -p /tmp/work; docker pull -q alpine >/dev/null 2>&1; echo ''echo app'' > /tmp/work/app.sh; true"]', '["sh", "-c", "( [ \\"$(docker image inspect -f ''{{.Config.WorkingDir}}'' wd:1)\\" = \\"/srv/app\\" ] ) && ( [ \\"$(docker run --rm wd:1 pwd 2>/dev/null)\\" = \\"/srv/app\\" ] ) && ( [ \\"$(docker run --rm wd:1 ls 2>/dev/null)\\" = \\"app.sh\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "이미지 작업 폴더가 /srv/app 이다", "cmd": ["sh", "-c", "[ \\"$(docker image inspect -f ''{{.Config.WorkingDir}}'' wd:1)\\" = \\"/srv/app\\" ]"]}, {"label": "컨테이너의 pwd 가 /srv/app 이다", "cmd": ["sh", "-c", "[ \\"$(docker run --rm wd:1 pwd 2>/dev/null)\\" = \\"/srv/app\\" ]"]}, {"label": "작업 폴더에 app.sh 가 들어 있다", "cmd": ["sh", "-c", "[ \\"$(docker run --rm wd:1 ls 2>/dev/null)\\" = \\"app.sh\\" ]"]}]', '[{"title": "Docker 공식 문서: Dockerfile reference", "url": "https://docs.docker.com/reference/dockerfile/"}, {"title": "Docker 공식 문서: 빌드 변수 (ARG, ENV)", "url": "https://docs.docker.com/build/building/variables/"}, {"title": "Docker 공식 문서: 빌드 캐시", "url": "https://docs.docker.com/build/cache/"}, {"title": "Docker 공식 문서: 멀티 스테이지 빌드", "url": "https://docs.docker.com/build/building/multi-stage/"}, {"title": "Docker 공식 문서: 빌드 컨텍스트와 .dockerignore", "url": "https://docs.docker.com/build/concepts/context/"}, {"title": "Docker 공식 문서: docker image inspect", "url": "https://docs.docker.com/reference/cli/docker/image/inspect/"}]'),
  (346, 3, 'CMD 는 실행할 때 갈아끼울 수 있다', '이미지 `cmd:1` 은 기본으로 `default` 를 출력하는 `CMD` 를 가지고 있습니다. 이미지는 건드리지 말고, **컨테이너를 실행할 때** `docker run` 에 명령을 붙여서 대신 `changed` 를 출력하게 하고, 그 출력을 `/tmp/work/out.txt` 에 저장하세요.', '`docker run 이미지` 뒤에 명령을 적으면 이미지의 `CMD` 가 그 명령으로 **대체**돼요. 출력은 `>` 로 파일에 넘깁니다. 이미지에 적힌 CMD 자체는 그대로 남습니다.', 'docker run --rm cmd:1
docker run --rm cmd:1 echo changed > /tmp/work/out.txt
cat /tmp/work/out.txt

# CMD 는 기본값일 뿐이라 run 뒤의 명령이 이긴다', '["sh", "-c", "docker rm -f $(docker ps -aq) >/dev/null 2>&1; docker rmi -f $(docker images -aq) >/dev/null 2>&1; rm -rf /tmp/work; mkdir -p /tmp/work; docker pull -q alpine >/dev/null 2>&1; printf ''FROM alpine\\\\nCMD [\\"echo\\",\\"default\\"]\\\\n'' > /tmp/work/Dockerfile; docker build -q -t cmd:1 /tmp/work >/dev/null 2>&1; true"]', '["sh", "-c", "( [ \\"$(cat /tmp/work/out.txt 2>/dev/null)\\" = \\"changed\\" ] ) && ( docker image inspect -f ''{{json .Config.Cmd}}'' cmd:1 | grep -q default )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "out.txt 에 changed 가 들어 있다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/work/out.txt 2>/dev/null)\\" = \\"changed\\" ]"]}, {"label": "이미지의 CMD 는 그대로다", "cmd": ["sh", "-c", "docker image inspect -f ''{{json .Config.Cmd}}'' cmd:1 | grep -q default"]}]', '[{"title": "Docker 공식 문서: Dockerfile reference", "url": "https://docs.docker.com/reference/dockerfile/"}, {"title": "Docker 공식 문서: 빌드 변수 (ARG, ENV)", "url": "https://docs.docker.com/build/building/variables/"}, {"title": "Docker 공식 문서: 빌드 캐시", "url": "https://docs.docker.com/build/cache/"}, {"title": "Docker 공식 문서: 멀티 스테이지 빌드", "url": "https://docs.docker.com/build/building/multi-stage/"}, {"title": "Docker 공식 문서: 빌드 컨텍스트와 .dockerignore", "url": "https://docs.docker.com/build/concepts/context/"}, {"title": "Docker 공식 문서: docker image inspect", "url": "https://docs.docker.com/reference/cli/docker/image/inspect/"}]'),
  (346, 4, 'ENTRYPOINT 가 있을 때 run 인자는', '이미지가 `ENTRYPOINT ["echo", "A"]` 와 `CMD ["B"]` 를 가지고 있습니다. `docker run 이미지 C` 로 실행하면 무엇이 출력될까요?', 'ENTRYPOINT 는 "항상 실행할 프로그램", CMD 는 "그 프로그램에 넘길 기본 인자" 로 짝을 이뤄요. run 뒤에 적은 값이 어느 쪽 자리를 대신하는지 생각해 보세요.', NULL, NULL, '[]', 'choice', '["`A B C` 가 출력된다", "`C` 만 출력된다", "`A B` 가 출력된다", "`A C` 가 출력된다"]', 3, 'run 뒤에 적은 값은 **CMD 를 대체**하고 ENTRYPOINT 는 그대로 앞에 붙습니다. 그래서 `echo A C` 가 실행돼 `A C` 가 나와요. ENTRYPOINT 자체를 바꾸려면 `--entrypoint` 옵션이 따로 있어야 합니다.', NULL, NULL, NULL, '[{"title": "Docker 공식 문서: Dockerfile reference", "url": "https://docs.docker.com/reference/dockerfile/"}, {"title": "Docker 공식 문서: 빌드 변수 (ARG, ENV)", "url": "https://docs.docker.com/build/building/variables/"}, {"title": "Docker 공식 문서: 빌드 캐시", "url": "https://docs.docker.com/build/cache/"}, {"title": "Docker 공식 문서: 멀티 스테이지 빌드", "url": "https://docs.docker.com/build/building/multi-stage/"}, {"title": "Docker 공식 문서: 빌드 컨텍스트와 .dockerignore", "url": "https://docs.docker.com/build/concepts/context/"}, {"title": "Docker 공식 문서: docker image inspect", "url": "https://docs.docker.com/reference/cli/docker/image/inspect/"}]'),
  (346, 5, 'ENV 기본값과 run 에서 덮어쓰기', '이미지 `env:1` 은 `ENV MODE=prod` 를 가지고 있고 실행하면 `MODE` 값을 출력합니다. 이미지는 그대로 두고, 컨테이너 **`e1`** 을 실행하되 `MODE` 를 `dev` 로 바꿔서 띄우고, 그 컨테이너가 출력한 내용을 `/tmp/work/mode.txt` 에 저장하세요.', '`ENV` 는 이미지에 박힌 **기본값**이고 `docker run` 의 `-e 이름=값` 이 그것을 덮어써요. 이름은 `--name` 으로 정하고, 컨테이너가 출력한 내용은 `docker logs` 로 볼 수 있습니다.', 'docker run --name e1 -e MODE=dev env:1
docker logs e1 > /tmp/work/mode.txt
cat /tmp/work/mode.txt

# 이미지의 ENV 는 prod 그대로 남는다', '["sh", "-c", "docker rm -f $(docker ps -aq) >/dev/null 2>&1; docker rmi -f $(docker images -aq) >/dev/null 2>&1; rm -rf /tmp/work; mkdir -p /tmp/work; docker pull -q alpine >/dev/null 2>&1; printf ''FROM alpine\\\\nENV MODE=prod\\\\nCMD [\\"sh\\",\\"-c\\",\\"echo $MODE\\"]\\\\n'' > /tmp/work/Dockerfile; docker build -q -t env:1 /tmp/work >/dev/null 2>&1; true"]', '["sh", "-c", "( docker inspect -f ''{{json .Config.Env}}'' e1 | grep -q ''MODE=dev'' ) && ( [ \\"$(cat /tmp/work/mode.txt 2>/dev/null)\\" = \\"dev\\" ] ) && ( docker image inspect -f ''{{.Config.Env}}'' env:1 | grep -q ''MODE=prod'' )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "e1 컨테이너의 MODE 가 dev 다", "cmd": ["sh", "-c", "docker inspect -f ''{{json .Config.Env}}'' e1 | grep -q ''MODE=dev''"]}, {"label": "mode.txt 에 dev 가 들어 있다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/work/mode.txt 2>/dev/null)\\" = \\"dev\\" ]"]}, {"label": "이미지의 기본값은 prod 그대로다", "cmd": ["sh", "-c", "docker image inspect -f ''{{.Config.Env}}'' env:1 | grep -q ''MODE=prod''"]}]', '[{"title": "Docker 공식 문서: Dockerfile reference", "url": "https://docs.docker.com/reference/dockerfile/"}, {"title": "Docker 공식 문서: 빌드 변수 (ARG, ENV)", "url": "https://docs.docker.com/build/building/variables/"}, {"title": "Docker 공식 문서: 빌드 캐시", "url": "https://docs.docker.com/build/cache/"}, {"title": "Docker 공식 문서: 멀티 스테이지 빌드", "url": "https://docs.docker.com/build/building/multi-stage/"}, {"title": "Docker 공식 문서: 빌드 컨텍스트와 .dockerignore", "url": "https://docs.docker.com/build/concepts/context/"}, {"title": "Docker 공식 문서: docker image inspect", "url": "https://docs.docker.com/reference/cli/docker/image/inspect/"}]'),
  (346, 6, 'ARG 값을 ENV 로 이어서 남기기', '`/tmp/work/Dockerfile` 은 빌드 인자 `VER`(기본값 `1.0`)를 받아 `ENV APP_VER=$VER` 로 이미지에 남기게 되어 있습니다. 빌드할 때 `VER` 를 **`2.5`** 로 넘겨 이미지 **`ver:1`** 을 만드세요. 컨테이너를 실행하면 `2.5` 가 출력되어야 합니다.', '빌드 중에만 쓰는 값은 `docker build` 의 `--build-arg 이름=값` 으로 넘겨요. `ARG` 자체는 이미지에 남지 않지만, 위처럼 `ENV` 에 옮겨 담으면 실행 환경에도 남습니다.', 'cd /tmp/work
docker build --build-arg VER=2.5 -t ver:1 .
docker run --rm ver:1

# ARG 는 빌드 때만, ENV 는 실행 때도 보인다. VER 은 이미지 Env 에 없고 APP_VER 만 남는다', '["sh", "-c", "docker rm -f $(docker ps -aq) >/dev/null 2>&1; docker rmi -f $(docker images -aq) >/dev/null 2>&1; rm -rf /tmp/work; mkdir -p /tmp/work; docker pull -q alpine >/dev/null 2>&1; printf ''FROM alpine\\\\nARG VER=1.0\\\\nENV APP_VER=$VER\\\\nCMD [\\"sh\\",\\"-c\\",\\"echo $APP_VER\\"]\\\\n'' > /tmp/work/Dockerfile; true"]', '["sh", "-c", "( [ \\"$(docker run --rm ver:1  2>/dev/null)\\" = \\"2.5\\" ] ) && ( docker image inspect -f ''{{json .Config.Env}}'' ver:1 | grep -q ''APP_VER=2.5'' ) && ( ! docker image inspect -f ''{{range .Config.Env}}{{println .}}{{end}}'' ver:1 | grep -q ''^VER='' )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "ver:1 이 실행되면 2.5 를 출력한다", "cmd": ["sh", "-c", "[ \\"$(docker run --rm ver:1  2>/dev/null)\\" = \\"2.5\\" ]"]}, {"label": "이미지 Env 에 APP_VER=2.5 가 있다", "cmd": ["sh", "-c", "docker image inspect -f ''{{json .Config.Env}}'' ver:1 | grep -q ''APP_VER=2.5''"]}, {"label": "ARG 이름 VER 은 Env 에 남지 않는다", "cmd": ["sh", "-c", "! docker image inspect -f ''{{range .Config.Env}}{{println .}}{{end}}'' ver:1 | grep -q ''^VER=''"]}]', '[{"title": "Docker 공식 문서: Dockerfile reference", "url": "https://docs.docker.com/reference/dockerfile/"}, {"title": "Docker 공식 문서: 빌드 변수 (ARG, ENV)", "url": "https://docs.docker.com/build/building/variables/"}, {"title": "Docker 공식 문서: 빌드 캐시", "url": "https://docs.docker.com/build/cache/"}, {"title": "Docker 공식 문서: 멀티 스테이지 빌드", "url": "https://docs.docker.com/build/building/multi-stage/"}, {"title": "Docker 공식 문서: 빌드 컨텍스트와 .dockerignore", "url": "https://docs.docker.com/build/concepts/context/"}, {"title": "Docker 공식 문서: docker image inspect", "url": "https://docs.docker.com/reference/cli/docker/image/inspect/"}]'),
  (346, 7, '다른 단계에서 파일 가져오기', '멀티 스테이지 Dockerfile 의 첫 단계는 `FROM alpine AS builder` 이고 `/out/app` 파일을 만듭니다. 두 번째 단계에서 그 파일을 `/app` 으로 **첫 단계로부터** 가져오는 줄의 빈칸을 채우세요.', '`COPY` 에 `--from=` 옵션을 주면 호스트 폴더 대신 다른 단계(또는 이미지)의 파일을 가져와요. `=` 뒤에는 `AS` 로 붙인 단계 이름을 적습니다.', NULL, NULL, '[]', 'fill', '["builder", "build1", "stage", "latest"]', NULL, '`FROM ... AS builder` 로 이름 붙인 단계를 `COPY --from=builder` 로 참조합니다. 이렇게 하면 빌드 도구는 첫 단계에만 있고 최종 이미지에는 **결과 파일만** 들어가 가벼워져요. 단계 번호(`--from=0`)도 쓸 수 있지만 이름이 읽기 쉽습니다.', '[0]', 'COPY --from={0} /out/app /app', NULL, '[{"title": "Docker 공식 문서: Dockerfile reference", "url": "https://docs.docker.com/reference/dockerfile/"}, {"title": "Docker 공식 문서: 빌드 변수 (ARG, ENV)", "url": "https://docs.docker.com/build/building/variables/"}, {"title": "Docker 공식 문서: 빌드 캐시", "url": "https://docs.docker.com/build/cache/"}, {"title": "Docker 공식 문서: 멀티 스테이지 빌드", "url": "https://docs.docker.com/build/building/multi-stage/"}, {"title": "Docker 공식 문서: 빌드 컨텍스트와 .dockerignore", "url": "https://docs.docker.com/build/concepts/context/"}, {"title": "Docker 공식 문서: docker image inspect", "url": "https://docs.docker.com/reference/cli/docker/image/inspect/"}]'),
  (346, 8, '캐시가 살아 있는 재빌드', '`/tmp/work` 에서 이미지 `cache:1` 이 이미 빌드되어 있습니다. `app.txt` 의 내용을 바꾼 뒤 **`cache:2`** 로 다시 빌드하세요. 단, `--no-cache` 는 쓰지 않고, `deps.txt` 를 복사하고 `RUN` 하는 앞쪽 단계는 **캐시를 재사용**해서 `cache:1` 과 레이어를 공유해야 합니다.', '도커는 위에서부터 단계를 비교하다가 처음 달라진 단계부터 다시 만들어요. `app.txt` 를 복사하는 줄이 Dockerfile 맨 아래에 있는지 확인해 보세요. 확인은 `docker history 이미지` 로 단계별 레이어를 비교합니다.', 'cd /tmp/work
cat Dockerfile
echo changed >> app.txt
docker build -t cache:2 .
docker history cache:2

# 바뀐 줄 위쪽 단계는 그대로(CACHED) 재사용되고, 바뀐 줄부터 새로 만든다', '["sh", "-c", "docker rm -f $(docker ps -aq) >/dev/null 2>&1; docker rmi -f $(docker images -aq) >/dev/null 2>&1; rm -rf /tmp/work; mkdir -p /tmp/work; docker pull -q alpine >/dev/null 2>&1; cd /tmp/work; echo base > deps.txt; echo v1 > app.txt; printf ''FROM alpine\\\\nCOPY deps.txt /deps.txt\\\\nRUN wc -c < /deps.txt > /size.txt\\\\nCOPY app.txt /app.txt\\\\n'' > Dockerfile; docker build -q -t cache:1 . >/dev/null 2>&1; true"]', '["sh", "-c", "( docker image inspect cache:2 >/dev/null 2>&1 ) && ( [ \\"$(docker run --rm cache:1 cat /app.txt)\\" != \\"$(docker run --rm cache:2 cat /app.txt)\\" ] ) && ( [ \\"$(docker image inspect -f ''{{index .RootFS.Layers 2}}'' cache:1)\\" = \\"$(docker image inspect -f ''{{index .RootFS.Layers 2}}'' cache:2)\\" ] ) && ( [ \\"$(docker image inspect -f ''{{index .RootFS.Layers 3}}'' cache:1)\\" != \\"$(docker image inspect -f ''{{index .RootFS.Layers 3}}'' cache:2)\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "cache:2 이미지가 있다", "cmd": ["sh", "-c", "docker image inspect cache:2 >/dev/null 2>&1"]}, {"label": "app.txt 내용이 cache:1 과 다르다", "cmd": ["sh", "-c", "[ \\"$(docker run --rm cache:1 cat /app.txt)\\" != \\"$(docker run --rm cache:2 cat /app.txt)\\" ]"]}, {"label": "앞쪽 레이어는 cache:1 과 같다 (캐시 재사용)", "cmd": ["sh", "-c", "[ \\"$(docker image inspect -f ''{{index .RootFS.Layers 2}}'' cache:1)\\" = \\"$(docker image inspect -f ''{{index .RootFS.Layers 2}}'' cache:2)\\" ]"]}, {"label": "app.txt 레이어는 새로 만들어졌다", "cmd": ["sh", "-c", "[ \\"$(docker image inspect -f ''{{index .RootFS.Layers 3}}'' cache:1)\\" != \\"$(docker image inspect -f ''{{index .RootFS.Layers 3}}'' cache:2)\\" ]"]}]', '[{"title": "Docker 공식 문서: Dockerfile reference", "url": "https://docs.docker.com/reference/dockerfile/"}, {"title": "Docker 공식 문서: 빌드 변수 (ARG, ENV)", "url": "https://docs.docker.com/build/building/variables/"}, {"title": "Docker 공식 문서: 빌드 캐시", "url": "https://docs.docker.com/build/cache/"}, {"title": "Docker 공식 문서: 멀티 스테이지 빌드", "url": "https://docs.docker.com/build/building/multi-stage/"}, {"title": "Docker 공식 문서: 빌드 컨텍스트와 .dockerignore", "url": "https://docs.docker.com/build/concepts/context/"}, {"title": "Docker 공식 문서: docker image inspect", "url": "https://docs.docker.com/reference/cli/docker/image/inspect/"}]'),
  (346, 9, '.dockerignore 로 빼고 예외 두기', '`/tmp/work` 에는 `Dockerfile`(`COPY . /data/`), `notes.txt`, `a.log`, `important.log`, 그리고 `tmp/` 폴더가 있습니다. `.dockerignore` 를 써서 **모든 `.log` 파일과 `tmp/` 폴더는 이미지에 넣지 않되, `important.log` 만은 넣도록** 한 뒤 이미지 **`ign:1`** 을 빌드하세요.', '`.dockerignore` 는 한 줄에 패턴 하나이고 `*.log` 처럼 와일드카드를 쓸 수 있어요. 줄 앞에 `!` 를 붙이면 앞에서 뺀 것 중 일부를 **다시 포함**시킵니다. 순서가 중요해요(뒤 줄이 이깁니다).', 'cd /tmp/work
printf ''*.log\\n!important.log\\ntmp/\\n'' > .dockerignore
docker build -t ign:1 .
docker run --rm ign:1 ls /data

# 뺄 것을 먼저, 예외(!)는 그 뒤에 적는다', '["sh", "-c", "docker rm -f $(docker ps -aq) >/dev/null 2>&1; docker rmi -f $(docker images -aq) >/dev/null 2>&1; rm -rf /tmp/work; mkdir -p /tmp/work; docker pull -q alpine >/dev/null 2>&1; cd /tmp/work; echo n > notes.txt; echo a > a.log; echo i > important.log; mkdir tmp; echo t > tmp/x.txt; printf ''FROM alpine\\\\nCOPY . /data/\\\\n'' > Dockerfile; true"]', '["sh", "-c", "( docker run --rm ign:1 sh -c ''test -f /data/notes.txt && test -f /data/important.log'' ) && ( docker run --rm ign:1 test ! -e /data/a.log ) && ( docker run --rm ign:1 test ! -e /data/tmp )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "notes.txt 와 important.log 는 들어 있다", "cmd": ["sh", "-c", "docker run --rm ign:1 sh -c ''test -f /data/notes.txt && test -f /data/important.log''"]}, {"label": "a.log 는 빠져 있다", "cmd": ["sh", "-c", "docker run --rm ign:1 test ! -e /data/a.log"]}, {"label": "tmp 폴더는 빠져 있다", "cmd": ["sh", "-c", "docker run --rm ign:1 test ! -e /data/tmp"]}]', '[{"title": "Docker 공식 문서: Dockerfile reference", "url": "https://docs.docker.com/reference/dockerfile/"}, {"title": "Docker 공식 문서: 빌드 변수 (ARG, ENV)", "url": "https://docs.docker.com/build/building/variables/"}, {"title": "Docker 공식 문서: 빌드 캐시", "url": "https://docs.docker.com/build/cache/"}, {"title": "Docker 공식 문서: 멀티 스테이지 빌드", "url": "https://docs.docker.com/build/building/multi-stage/"}, {"title": "Docker 공식 문서: 빌드 컨텍스트와 .dockerignore", "url": "https://docs.docker.com/build/concepts/context/"}, {"title": "Docker 공식 문서: docker image inspect", "url": "https://docs.docker.com/reference/cli/docker/image/inspect/"}]'),
  (346, 10, '멀티 스테이지로 결과 파일만 담기', '`/tmp/work/Dockerfile` 을 **두 단계**로 써서 이미지 **`ms:1`** 을 빌드하세요. 첫 단계(`alpine`, 이름 `builder`)에서 `RUN` 으로 `/out/result.txt` 에 `built-in-stage-one` 을 적어 만들고, 두 번째 단계(`alpine`)는 그 파일만 `/result.txt` 로 가져옵니다. 최종 이미지에는 `/out` 폴더가 없어야 합니다.', '단계마다 `FROM` 을 새로 쓰고, 첫 단계는 `AS 이름` 을 붙여요. 두 번째 단계에서 `COPY --from=이름 원본 도착` 으로 가져옵니다. 최종 이미지는 **마지막 단계**의 내용이에요.', 'cd /tmp/work
printf ''FROM alpine AS builder\\nRUN mkdir /out && echo built-in-stage-one > /out/result.txt\\nFROM alpine\\nCOPY --from=builder /out/result.txt /result.txt\\n'' > Dockerfile
docker build -t ms:1 .
docker run --rm ms:1 cat /result.txt

# 첫 단계의 나머지(/out 폴더 등)는 최종 이미지에 들어가지 않는다', '["sh", "-c", "docker rm -f $(docker ps -aq) >/dev/null 2>&1; docker rmi -f $(docker images -aq) >/dev/null 2>&1; rm -rf /tmp/work; mkdir -p /tmp/work; docker pull -q alpine >/dev/null 2>&1; true"]', '["sh", "-c", "( docker image inspect ms:1 >/dev/null 2>&1 ) && ( [ \\"$(docker run --rm ms:1 cat /result.txt 2>/dev/null)\\" = \\"built-in-stage-one\\" ] ) && ( docker run --rm ms:1 test ! -e /out ) && ( [ \\"$(grep -ci ''^FROM'' /tmp/work/Dockerfile)\\" -ge 2 ] ) && ( grep -q -e ''--from'' /tmp/work/Dockerfile )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "ms:1 이미지가 있다", "cmd": ["sh", "-c", "docker image inspect ms:1 >/dev/null 2>&1"]}, {"label": "/result.txt 내용이 맞다", "cmd": ["sh", "-c", "[ \\"$(docker run --rm ms:1 cat /result.txt 2>/dev/null)\\" = \\"built-in-stage-one\\" ]"]}, {"label": "/out 폴더는 최종 이미지에 없다", "cmd": ["sh", "-c", "docker run --rm ms:1 test ! -e /out"]}, {"label": "Dockerfile 에 FROM 이 두 번 이상 있다", "cmd": ["sh", "-c", "[ \\"$(grep -ci ''^FROM'' /tmp/work/Dockerfile)\\" -ge 2 ]"]}, {"label": "Dockerfile 이 --from 으로 복사한다", "cmd": ["sh", "-c", "grep -q -e ''--from'' /tmp/work/Dockerfile"]}]', '[{"title": "Docker 공식 문서: Dockerfile reference", "url": "https://docs.docker.com/reference/dockerfile/"}, {"title": "Docker 공식 문서: 빌드 변수 (ARG, ENV)", "url": "https://docs.docker.com/build/building/variables/"}, {"title": "Docker 공식 문서: 빌드 캐시", "url": "https://docs.docker.com/build/cache/"}, {"title": "Docker 공식 문서: 멀티 스테이지 빌드", "url": "https://docs.docker.com/build/building/multi-stage/"}, {"title": "Docker 공식 문서: 빌드 컨텍스트와 .dockerignore", "url": "https://docs.docker.com/build/concepts/context/"}, {"title": "Docker 공식 문서: docker image inspect", "url": "https://docs.docker.com/reference/cli/docker/image/inspect/"}]'),
  (346, 11, 'root 가 아닌 사용자로 실행하기', '`/tmp/work/Dockerfile` 은 `app` 사용자를 만들고 `id -un` 을 실행하는 이미지를 만들지만, 아직 컨테이너가 `root` 로 돕니다. Dockerfile 을 고쳐서 컨테이너가 **`app`** 사용자로 실행되게 하고, 이미지 **`nonroot:1`** 을 빌드하세요.', '`USER 이름` 지시어를 쓰면 그 줄 **이후**의 `RUN`·`CMD` 와 컨테이너 실행이 그 사용자로 돼요. 사용자를 만드는 `RUN` 이 먼저 와야 합니다. 이미지 설정의 `Config.User` 로 확인할 수 있어요.', 'cd /tmp/work
printf ''FROM alpine\\nRUN adduser -D app\\nUSER app\\nCMD ["id","-un"]\\n'' > Dockerfile
docker build -t nonroot:1 .
docker run --rm nonroot:1

# USER 를 쓰지 않으면 기본은 root', '["sh", "-c", "docker rm -f $(docker ps -aq) >/dev/null 2>&1; docker rmi -f $(docker images -aq) >/dev/null 2>&1; rm -rf /tmp/work; mkdir -p /tmp/work; docker pull -q alpine >/dev/null 2>&1; printf ''FROM alpine\\\\nRUN adduser -D app\\\\nCMD [\\"id\\",\\"-un\\"]\\\\n'' > /tmp/work/Dockerfile; true"]', '["sh", "-c", "( [ \\"$(docker image inspect -f ''{{.Config.User}}'' nonroot:1)\\" = \\"app\\" ] ) && ( [ \\"$(docker run --rm nonroot:1  2>/dev/null)\\" = \\"app\\" ] ) && ( [ \\"$(docker run --rm nonroot:1 id -u)\\" != 0 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "이미지 Config.User 가 app 이다", "cmd": ["sh", "-c", "[ \\"$(docker image inspect -f ''{{.Config.User}}'' nonroot:1)\\" = \\"app\\" ]"]}, {"label": "컨테이너가 app 으로 실행된다", "cmd": ["sh", "-c", "[ \\"$(docker run --rm nonroot:1  2>/dev/null)\\" = \\"app\\" ]"]}, {"label": "root 로 실행되지 않는다", "cmd": ["sh", "-c", "[ \\"$(docker run --rm nonroot:1 id -u)\\" != 0 ]"]}]', '[{"title": "Docker 공식 문서: Dockerfile reference", "url": "https://docs.docker.com/reference/dockerfile/"}, {"title": "Docker 공식 문서: 빌드 변수 (ARG, ENV)", "url": "https://docs.docker.com/build/building/variables/"}, {"title": "Docker 공식 문서: 빌드 캐시", "url": "https://docs.docker.com/build/cache/"}, {"title": "Docker 공식 문서: 멀티 스테이지 빌드", "url": "https://docs.docker.com/build/building/multi-stage/"}, {"title": "Docker 공식 문서: 빌드 컨텍스트와 .dockerignore", "url": "https://docs.docker.com/build/concepts/context/"}, {"title": "Docker 공식 문서: docker image inspect", "url": "https://docs.docker.com/reference/cli/docker/image/inspect/"}]'),
  (346, 12, 'Dockerfile 을 캐시에 좋은 순서로 쓰기', '자주 바뀌지 않는 것을 위에, 자주 바뀌는 것을 아래에 두는 **캐시 친화적인** Dockerfile 의 줄 순서를 앞에서 뒤로 놓으세요.', '시작 이미지가 맨 위, 실행 설정이 맨 아래예요. 그 사이에서는 "잘 안 바뀌는 의존성 단계"가 위, "매번 바뀌는 소스 복사"가 아래입니다.', NULL, NULL, '[]', 'order', '["`FROM alpine` 으로 시작 이미지를 정한다", "`WORKDIR /app` 으로 작업 폴더를 정한다", "`COPY deps.txt .` 로 잘 안 바뀌는 의존성 목록만 복사한다", "`RUN` 으로 의존성 설치 단계를 실행한다", "`COPY . .` 로 자주 바뀌는 소스를 복사한다", "`CMD [\\"sh\\", \\"app.sh\\"]` 로 기본 실행 명령을 정한다"]', NULL, '**FROM → WORKDIR → COPY(의존성) → RUN(설치) → COPY(소스) → CMD** 순서입니다. 소스는 매번 바뀌어서 그 줄부터 캐시가 깨지므로, 시간이 오래 걸리는 설치 단계는 소스 복사보다 **위에** 둬야 재사용돼요.', '[0, 1, 2, 3, 4, 5]', NULL, NULL, '[{"title": "Docker 공식 문서: Dockerfile reference", "url": "https://docs.docker.com/reference/dockerfile/"}, {"title": "Docker 공식 문서: 빌드 변수 (ARG, ENV)", "url": "https://docs.docker.com/build/building/variables/"}, {"title": "Docker 공식 문서: 빌드 캐시", "url": "https://docs.docker.com/build/cache/"}, {"title": "Docker 공식 문서: 멀티 스테이지 빌드", "url": "https://docs.docker.com/build/building/multi-stage/"}, {"title": "Docker 공식 문서: 빌드 컨텍스트와 .dockerignore", "url": "https://docs.docker.com/build/concepts/context/"}, {"title": "Docker 공식 문서: docker image inspect", "url": "https://docs.docker.com/reference/cli/docker/image/inspect/"}]');
